('advanced-native-1216', '["phrase"]'::jsonb, '{"advanced-native-1216-v1-audio":{"type":"mc","answers":["The question continued to occupy the speaker’s thoughts after the discussion."],"options":["The question returned to the speaker only when someone repeated the discussion word for word on the bus.","The question continued to occupy the speaker’s thoughts after the discussion.","The speaker only remembered the wording while it was being read aloud.","The group had already agreed on the character’s exact motive and no questions remained."]},"advanced-native-1216-v2-reply":{"type":"mc","answers":["It made me keep considering the character’s hidden letter.","The discussion ended before my interest in the motive did.","It left an echo because I was still thinking about the choice afterwards.","The unresolved question gave me something to reflect on beyond the session."],"options":["It made me keep considering the character’s hidden letter.","The discussion ended before my interest in the motive did.","It left an echo because I was still thinking about the choice afterwards.","The unresolved question gave me something to reflect on beyond the session."]},"advanced-native-1216-v1-scene":{"type":"mc","answers":["The letter left an echo that shaped how she wanted to write the captions."],"options":["She remembered nothing of the letter once she put it away.","The account is only about the volume of a voice in an empty room.","The letter left an echo that shaped how she wanted to write the captions."]},"advanced-native-1216-v1-contrast":{"type":"mc","answers":["A sound is measured only for its volume, with no later thought or feeling described."],"options":["A performance affects how a listener later thinks about a familiar memory.","A sound is measured only for its volume, with no later thought or feeling described.","Someone returns to a question after the conversation has ended."]},"advanced-native-1216-v1-branch":{"type":"mc","answers":["The question left an echo for me, but I cannot describe everyone else’s later feelings."],"options":["The question stayed with our whole group on the way home, as my own journey shows.","I meant the excitement while we discussed the question, rather than a thought that continued afterwards.","The question left an echo for me, but I cannot describe everyone else’s later feelings."]},"advanced-native-1216-v1-final":{"type":"open","answers":["Your closing melody left an echo for me; I thought of the farewell again when I passed the old pier the next day. Could we keep a few quiet seconds after it rather than cover the ending with another sound?","The music leaves an echo in my memory of the farewell, so I would leave a short silence at the end. That is my response, rather than a claim about what every viewer will remember."],"options":[]}}'::jsonb),
('advanced-native-1217', '["phrase"]'::jsonb, '{"advanced-native-1217-v1-audio":{"type":"mc","answers":["It was one visible sign of a wider filing problem that was not fully checked yet."],"options":["The new check showed that all the books had already moved to the new system.","The speaker already knew the exact total of affected books in every room.","It was one visible sign of a wider filing problem that was not fully checked yet.","It was the only incorrect item, as every shelf and the back room had already been checked."]},"advanced-native-1217-v2-reply":{"type":"mc","answers":["The next shelf showed that the issue extended beyond a single book.","We had evidence of a wider problem, and the back room remained unchecked.","Fixing one label would not address the rest of the old filing we had found.","That label was the tip of the iceberg, with more old-system filing on the next shelf."],"options":["The next shelf showed that the issue extended beyond a single book.","We had evidence of a wider problem, and the back room remained unchecked.","Fixing one label would not address the rest of the old filing we had found.","That label was the tip of the iceberg, with more old-system filing on the next shelf."]},"advanced-native-1217-v1-scene":{"type":"mc","answers":["The first clash was the tip of the iceberg; more bookings need checking."],"options":["The first clash was the tip of the iceberg; more bookings need checking.","The first clash was a complete summary of every booking problem.","The remaining week has already been proved free of any duplicate booking."]},"advanced-native-1217-v1-contrast":{"type":"mc","answers":["A complete check confirms one isolated error and no wider related issue."],"options":["A first error leads to evidence of many related errors not yet fully explored.","A complete check confirms one isolated error and no wider related issue.","A small public example is known to belong to a larger hidden pattern."]},"advanced-native-1217-v1-branch":