('advanced-native-1218', '["phrase"]'::jsonb, '{"advanced-native-1218-v1-audio":{"type":"mc","answers":["The dancer uses movement to create her work and earns her living through performances."],"options":["The dancer only attends unpaid classes as an occasional hobby.","The dancer earns all her income from selling musical instruments.","The speaker says rehearsal plans cannot affect her working life.","The dancer uses movement to create her work and earns her living through performances."]},"advanced-native-1218-v2-reply":{"type":"mc","answers":["The work joins artistic expression with the income she depends on.","Decisions about performing also matter for how she earns a living.","Her movement is the medium of her work, and the performances pay her living costs.","Her body is both her instrument and her livelihood."],"options":["The work joins artistic expression with the income she depends on.","Decisions about performing also matter for how she earns a living.","Her movement is the medium of her work, and the performances pay her living costs.","Her body is both her instrument and her livelihood."]},"advanced-native-1218-v1-scene":{"type":"mc","answers":["Her body is an instrument for the performance, but this account does not make it her livelihood."],"options":["The translation income shows that she uses words rather than movement in the performance.","Her body is an instrument for the performance, but this account does not make it her livelihood.","Her body is both her instrument and her livelihood because she performs at weekends."]},"advanced-native-1218-v1-contrast":{"type":"mc","answers":["An unpaid hobbyist enjoys an occasional movement class but earns their living elsewhere."],"options":["A paid dancer relies on bodily movement to create performances and earn income.","An unpaid hobbyist enjoys an occasional movement class but earns their living elsewhere.","A professional performer’s physical skills underpin work that pays their living costs."]},"advanc