('advanced-native-1222', '["phrase"]'::jsonb, '{"advanced-native-1222-v1-audio":{"type":"mc","answers":["Supporting the writer while giving clear feedback about a real difficulty."],"options":["Supporting the writer while giving clear feedback about a real difficulty.","Avoiding every criticism so the writer would never hear about the ending.","Giving only negative comments to make encouragement unnecessary.","Dividing the draft into two exactly equal halves regardless of what needed attention."]},"advanced-native-1222-v2-reply":{"type":"mc","answers":["I aimed to be kind and specific rather than either vague or discouraging.","I wanted the writer to feel supported without hiding the difficulty.","I was trying to walk a fine line between encouragement and clear criticism.","The useful parts deserved recognition, and the ending still needed explanation."],"options":["I aimed to be kind and specific rather than either vague or discouraging.","I wanted the writer to feel supported without hiding the difficulty.","I was trying to walk a fine line between encouragement and clear criticism.","The useful parts deserved recognition, and the ending still needed explanation."]},"advanced-native-1222-v1-scene":{"type":"mc","answers":["He is walking a fine line between offering support and taking over the answer."],"options":["He is waiting because he wants the newcomer to manage without any offer of a prompt.","He is walking a fine line between offering support and taking over the answer.","He is treating an immediate prompt as the best support, before allowing the newcomer time to think."]},"advanced-native-1222-v1-contrast":{"type":"mc","answers":["The phrase requires giving each side exactly half of the time or words."],"options":["A useful response may combine the two aims in different amounts.","The phrase requires giving each side exactly half of the time or words.","The action needs care because either extreme could cause a problem."]},"advanced-native-1222-v1-branch":{